"""Apply the exact tested status-safety patch; removed after validation."""
from pathlib import Path
import base64
import gzip
import hashlib
import subprocess

DATA = """"""
patch = gzip.decompress(base64.b64decode(DATA, validate=True))
if len(patch) != 14145 or hashlib.sha256(patch).hexdigest() != "3e6138d18921471af04bef66424da7e99fc971baba1a2bb7c6287deb57c91f92":
    raise RuntimeError("status-safety patch integrity mismatch")
root = Path(__file__).resolve().parents[1]
subprocess.run(["git", "apply", "--check", "--whitespace=error-all", "-"], cwd=root, input=patch, check=True)
